CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key. Internal only - nothing outside the database identifies an account by it.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The account identity, in E.164 form. There is no username and no email: the number is the login, the address book key and the account recovery path.
	"phone_e164" VARCHAR(20) NOT NULL UNIQUE,
	-- The name the user chose for themselves. Almost nobody sees it, because contacts override it with their own label.
	"display_name" VARCHAR(60) NOT NULL,
	-- The status line on the profile. Null when cleared.
	"about_text" VARCHAR(160),
	-- CDN URL of the profile photo. Null when unset or hidden by privacy settings.
	"avatar_url" VARCHAR(500),
	-- Last connection. Null when the user hides last-seen, which is a real absence of data rather than a flag, so it cannot leak by accident.
	"last_seen_at" TIMESTAMP,
	-- When the number was first verified.
	"registered_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'One row per phone number. Re-registering the same number on a new phone reuses this row, which is why devices are a separate table.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key. Internal only - nothing outside the database identifies an account by it.';
COMMENT ON COLUMN "users"."phone_e164" IS 'The account identity, in E.164 form. There is no username and no email: the number is the login, the address book key and the account recovery path.';
COMMENT ON COLUMN "users"."display_name" IS 'The name the user chose for themselves. Almost nobody sees it, because contacts override it with their own label.';
COMMENT ON COLUMN "users"."about_text" IS 'The status line on the profile. Null when cleared.';
COMMENT ON COLUMN "users"."avatar_url" IS 'CDN URL of the profile photo. Null when unset or hidden by privacy settings.';
COMMENT ON COLUMN "users"."last_seen_at" IS 'Last connection. Null when the user hides last-seen, which is a real absence of data rather than a flag, so it cannot leak by accident.';
COMMENT ON COLUMN "users"."registered_at" IS 'When the number was first verified.';

CREATE TABLE IF NOT EXISTS "devices" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account this device is linked to.
	"user_id" BIGINT NOT NULL,
	-- android | ios | web | desktop. The primary phone and companion devices are the same kind of row.
	"platform" VARCHAR(20) NOT NULL,
	-- Exactly one device per account is primary; the rest were linked from it and can be revoked individually.
	"is_primary" BOOLEAN NOT NULL DEFAULT false,
	-- Public half of the device long-term key pair. Per device, not per account, which is what lets a linked laptop decrypt without holding the phone key.
	"identity_key" VARCHAR(255) NOT NULL,
	-- Platform push token. Null for a web session that holds an open socket instead.
	"push_token" VARCHAR(255),
	-- Client version, kept so a protocol change can be rolled out behind a floor.
	"app_version" VARCHAR(32),
	-- When the device was linked.
	"linked_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last time the device connected. Drives the "log out inactive devices" rule.
	"last_active_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "devices" IS 'Devices, not sessions. Multi-device means a message is encrypted once per recipient device, so this table is what the fan-out actually iterates over.';
COMMENT ON COLUMN "devices"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "devices"."user_id" IS 'Account this device is linked to.';
COMMENT ON COLUMN "devices"."platform" IS 'android | ios | web | desktop. The primary phone and companion devices are the same kind of row.';
COMMENT ON COLUMN "devices"."is_primary" IS 'Exactly one device per account is primary; the rest were linked from it and can be revoked individually.';
COMMENT ON COLUMN "devices"."identity_key" IS 'Public half of the device long-term key pair. Per device, not per account, which is what lets a linked laptop decrypt without holding the phone key.';
COMMENT ON COLUMN "devices"."push_token" IS 'Platform push token. Null for a web session that holds an open socket instead.';
COMMENT ON COLUMN "devices"."app_version" IS 'Client version, kept so a protocol change can be rolled out behind a floor.';
COMMENT ON COLUMN "devices"."linked_at" IS 'When the device was linked.';
COMMENT ON COLUMN "devices"."last_active_at" IS 'Last time the device connected. Drives the "log out inactive devices" rule.';

CREATE INDEX "idx_devices_user_primary"
ON "devices" ("user_id", "is_primary");

CREATE TABLE IF NOT EXISTS "contacts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Whose address book this entry belongs to. Contacts are private and never symmetric.
	"owner_user_id" BIGINT NOT NULL,
	-- The matched account. Null when the number is in the phone book but not registered, which is exactly the invite case.
	"contact_user_id" BIGINT,
	-- The number as normalised from the device address book. Kept even when contact_user_id is set, because the account can change its number.
	"phone_e164" VARCHAR(20) NOT NULL,
	-- The name the owner saved. This, not the other user display name, is what the UI shows everywhere.
	"local_name" VARCHAR(120) NOT NULL,
	-- Pins the contact in the picker.
	"is_favourite" BOOLEAN NOT NULL DEFAULT false,
	-- Last address-book sync; entries not seen in a sync are removed.
	"synced_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "contacts" IS 'A one-directional address book entry. The local name is the whole reason this table exists: the network shows you your names for people, not theirs.';
COMMENT ON COLUMN "contacts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "contacts"."owner_user_id" IS 'Whose address book this entry belongs to. Contacts are private and never symmetric.';
COMMENT ON COLUMN "contacts"."contact_user_id" IS 'The matched account. Null when the number is in the phone book but not registered, which is exactly the invite case.';
COMMENT ON COLUMN "contacts"."phone_e164" IS 'The number as normalised from the device address book. Kept even when contact_user_id is set, because the account can change its number.';
COMMENT ON COLUMN "contacts"."local_name" IS 'The name the owner saved. This, not the other user display name, is what the UI shows everywhere.';
COMMENT ON COLUMN "contacts"."is_favourite" IS 'Pins the contact in the picker.';
COMMENT ON COLUMN "contacts"."synced_at" IS 'Last address-book sync; entries not seen in a sync are removed.';

CREATE UNIQUE INDEX "uq_contacts_owner_phone"
ON "contacts" ("owner_user_id", "phone_e164");
CREATE INDEX "idx_contacts_contact_user"
ON "contacts" ("contact_user_id");

CREATE TABLE IF NOT EXISTS "chats" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- direct | group | broadcast. One table for all of them, because a message, a receipt and an unread count behave identically regardless.
	"kind" VARCHAR(16) NOT NULL,
	-- Group name. Null for a direct chat, where the title is rendered from the other participant contact name.
	"subject" VARCHAR(100),
	-- Group description. Null for direct chats.
	"description" VARCHAR(512),
	-- Group photo. Null for direct chats, which borrow the other participant avatar.
	"avatar_url" VARCHAR(500),
	-- Who created the group. Null once that account is deleted; the group survives.
	"created_by_user_id" BIGINT,
	-- Default lifetime applied to new messages in this chat. Null means messages never expire, which is the default.
	"disappearing_ttl_seconds" INTEGER,
	-- Announcement mode. Ignored for direct chats.
	"only_admins_can_post" BOOLEAN NOT NULL DEFAULT false,
	-- Newest message time, denormalised so the chat list sorts without touching the messages table.
	"last_message_at" TIMESTAMP,
	-- Chat creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "chats" IS 'Direct and group conversations in one entity. A direct chat is simply a chat with exactly two participants and no subject, which keeps every downstream table free of a special case.';
COMMENT ON COLUMN "chats"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "chats"."kind" IS 'direct | group | broadcast. One table for all of them, because a message, a receipt and an unread count behave identically regardless.';
COMMENT ON COLUMN "chats"."subject" IS 'Group name. Null for a direct chat, where the title is rendered from the other participant contact name.';
COMMENT ON COLUMN "chats"."description" IS 'Group description. Null for direct chats.';
COMMENT ON COLUMN "chats"."avatar_url" IS 'Group photo. Null for direct chats, which borrow the other participant avatar.';
COMMENT ON COLUMN "chats"."created_by_user_id" IS 'Who created the group. Null once that account is deleted; the group survives.';
COMMENT ON COLUMN "chats"."disappearing_ttl_seconds" IS 'Default lifetime applied to new messages in this chat. Null means messages never expire, which is the default.';
COMMENT ON COLUMN "chats"."only_admins_can_post" IS 'Announcement mode. Ignored for direct chats.';
COMMENT ON COLUMN "chats"."last_message_at" IS 'Newest message time, denormalised so the chat list sorts without touching the messages table.';
COMMENT ON COLUMN "chats"."created_at" IS 'Chat creation time.';

CREATE INDEX "idx_chats_kind_recent"
ON "chats" ("kind", "last_message_at");

CREATE TABLE IF NOT EXISTS "chat_participants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Conversation joined.
	"chat_id" BIGINT NOT NULL,
	-- Participant.
	"user_id" BIGINT NOT NULL,
	-- member | admin | owner. Meaningless in a direct chat, where both rows are members.
	"role" VARCHAR(16) NOT NULL DEFAULT 'member',
	-- Join time. Messages sent before it are not delivered to this participant, which is why the timestamp matters rather than just membership.
	"joined_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When they left or were removed. Null means still in the chat; the row is kept so their old messages keep an author.
	"left_at" TIMESTAMP,
	-- Mute expiry. Null means not muted.
	"is_muted_until" TIMESTAMP,
	-- Pins the chat to the top of this participant list only.
	"is_pinned" BOOLEAN NOT NULL DEFAULT false,
	-- Hides the chat from this participant main list without affecting anyone else.
	"is_archived" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "chat_participants" IS 'Membership plus every per-person chat setting. Leaving is a timestamp, not a delete, because removing the row would orphan the messages that person sent.';
COMMENT ON COLUMN "chat_participants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "chat_participants"."chat_id" IS 'Conversation joined.';
COMMENT ON COLUMN "chat_participants"."user_id" IS 'Participant.';
COMMENT ON COLUMN "chat_participants"."role" IS 'member | admin | owner. Meaningless in a direct chat, where both rows are members.';
COMMENT ON COLUMN "chat_participants"."joined_at" IS 'Join time. Messages sent before it are not delivered to this participant, which is why the timestamp matters rather than just membership.';
COMMENT ON COLUMN "chat_participants"."left_at" IS 'When they left or were removed. Null means still in the chat; the row is kept so their old messages keep an author.';
COMMENT ON COLUMN "chat_participants"."is_muted_until" IS 'Mute expiry. Null means not muted.';
COMMENT ON COLUMN "chat_participants"."is_pinned" IS 'Pins the chat to the top of this participant list only.';
COMMENT ON COLUMN "chat_participants"."is_archived" IS 'Hides the chat from this participant main list without affecting anyone else.';

CREATE UNIQUE INDEX "uq_chat_participants_chat_user"
ON "chat_participants" ("chat_id", "user_id");
CREATE INDEX "idx_chat_participants_user_archived"
ON "chat_participants" ("user_id", "is_archived");

CREATE TABLE IF NOT EXISTS "media" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Uploader. Null once the account is deleted, so a forwarded copy keeps working.
	"uploaded_by_user_id" BIGINT,
	-- image | video | audio | voice | document | sticker.
	"kind" VARCHAR(16) NOT NULL,
	-- Object-store URL of the ciphertext. The server never holds the plaintext or the key.
	"object_url" VARCHAR(500) NOT NULL,
	-- Opaque hint the client uses to locate the right key. Null for an unencrypted sticker from the public pack.
	"encryption_key_hint" VARCHAR(255),
	-- MIME type of the underlying file, needed before download to pick a renderer.
	"content_type" VARCHAR(120) NOT NULL,
	-- Ciphertext size, used to decide whether to auto-download on mobile data.
	"size_bytes" BIGINT NOT NULL,
	-- Playback length for audio and video. Null for images and documents.
	"duration_seconds" INTEGER,
	-- Visual width, so the bubble can be laid out before the bytes arrive.
	"width_px" INTEGER,
	-- Visual height, same reason.
	"height_px" INTEGER,
	-- Tiny inline preview shipped with the message itself. Null for documents.
	"thumbnail_blob" BYTEA,
	-- Upload time.
	"uploaded_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "media" IS 'Media is its own row so a forward reuses the stored object instead of re-uploading it. The server stores ciphertext and dimensions; it cannot read the content.';
COMMENT ON COLUMN "media"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "media"."uploaded_by_user_id" IS 'Uploader. Null once the account is deleted, so a forwarded copy keeps working.';
COMMENT ON COLUMN "media"."kind" IS 'image | video | audio | voice | document | sticker.';
COMMENT ON COLUMN "media"."object_url" IS 'Object-store URL of the ciphertext. The server never holds the plaintext or the key.';
COMMENT ON COLUMN "media"."encryption_key_hint" IS 'Opaque hint the client uses to locate the right key. Null for an unencrypted sticker from the public pack.';
COMMENT ON COLUMN "media"."content_type" IS 'MIME type of the underlying file, needed before download to pick a renderer.';
COMMENT ON COLUMN "media"."size_bytes" IS 'Ciphertext size, used to decide whether to auto-download on mobile data.';
COMMENT ON COLUMN "media"."duration_seconds" IS 'Playback length for audio and video. Null for images and documents.';
COMMENT ON COLUMN "media"."width_px" IS 'Visual width, so the bubble can be laid out before the bytes arrive.';
COMMENT ON COLUMN "media"."height_px" IS 'Visual height, same reason.';
COMMENT ON COLUMN "media"."thumbnail_blob" IS 'Tiny inline preview shipped with the message itself. Null for documents.';
COMMENT ON COLUMN "media"."uploaded_at" IS 'Upload time.';

CREATE TABLE IF NOT EXISTS "messages" (
	-- Surrogate primary key, monotonic so it orders a chat without trusting client clocks.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Conversation the message belongs to.
	"chat_id" BIGINT NOT NULL,
	-- Author. Null for a system event such as "Ana added Ben" or a security-code change notice.
	"sender_user_id" BIGINT,
	-- Attached media. Null for a text message.
	"media_id" BIGINT,
	-- Quoted message in the same chat. Null for a normal message; set null if the quoted row is purged by TTL.
	"reply_to_message_id" BIGINT,
	-- Ciphertext of the message body as stored server-side. Null for a media-only message.
	"body" TEXT,
	-- text | media | location | contact | poll | system.
	"kind" VARCHAR(20) NOT NULL DEFAULT 'text',
	-- sent | delivered | read | failed. A rollup of the receipt rows - the weakest state across recipients - cached so the chat list does not aggregate.
	"status" VARCHAR(16) NOT NULL DEFAULT 'sent',
	-- Drives the forwarded label, and the forward counter that limits viral chains.
	"is_forwarded" BOOLEAN NOT NULL DEFAULT false,
	-- Server receive time, which is the ordering authority.
	"sent_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last edit. Null means never edited.
	"edited_at" TIMESTAMP,
	-- Hard deletion time under the chat TTL. Null means the message is permanent; the value is computed once at send time from the chat setting then frozen.
	"expires_at" TIMESTAMP,
	-- Deleted for everyone. The row is tombstoned rather than removed so replies and receipts stay resolvable.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "messages" IS 'One row per message, whatever the chat size. The per-recipient state deliberately lives in message_receipts so this table is written once and then only rolled up.';
COMMENT ON COLUMN "messages"."id" IS 'Surrogate primary key, monotonic so it orders a chat without trusting client clocks.';
COMMENT ON COLUMN "messages"."chat_id" IS 'Conversation the message belongs to.';
COMMENT ON COLUMN "messages"."sender_user_id" IS 'Author. Null for a system event such as "Ana added Ben" or a security-code change notice.';
COMMENT ON COLUMN "messages"."media_id" IS 'Attached media. Null for a text message.';
COMMENT ON COLUMN "messages"."reply_to_message_id" IS 'Quoted message in the same chat. Null for a normal message; set null if the quoted row is purged by TTL.';
COMMENT ON COLUMN "messages"."body" IS 'Ciphertext of the message body as stored server-side. Null for a media-only message.';
COMMENT ON COLUMN "messages"."kind" IS 'text | media | location | contact | poll | system.';
COMMENT ON COLUMN "messages"."status" IS 'sent | delivered | read | failed. A rollup of the receipt rows - the weakest state across recipients - cached so the chat list does not aggregate.';
COMMENT ON COLUMN "messages"."is_forwarded" IS 'Drives the forwarded label, and the forward counter that limits viral chains.';
COMMENT ON COLUMN "messages"."sent_at" IS 'Server receive time, which is the ordering authority.';
COMMENT ON COLUMN "messages"."edited_at" IS 'Last edit. Null means never edited.';
COMMENT ON COLUMN "messages"."expires_at" IS 'Hard deletion time under the chat TTL. Null means the message is permanent; the value is computed once at send time from the chat setting then frozen.';
COMMENT ON COLUMN "messages"."deleted_at" IS 'Deleted for everyone. The row is tombstoned rather than removed so replies and receipts stay resolvable.';

CREATE INDEX "idx_messages_chat_id"
ON "messages" ("chat_id", "id");
CREATE INDEX "idx_messages_expiry"
ON "messages" ("expires_at");
CREATE INDEX "idx_messages_sender_sent"
ON "messages" ("sender_user_id", "sent_at");

CREATE TABLE IF NOT EXISTS "message_receipts" (
	-- Message being tracked, part of the composite key.
	"message_id" BIGINT,
	-- Recipient, part of the key. One row per recipient is the fan-out: a 200-person group produces 200 rows per message.
	"recipient_user_id" BIGINT,
	-- When the recipient device acknowledged receipt. Null means the second tick has not appeared.
	"delivered_at" TIMESTAMP,
	-- When the recipient opened the chat past this message. Null means unread, or that they disabled read receipts.
	"read_at" TIMESTAMP,
	-- When a voice note was played, which is a third state text messages do not have.
	"played_at" TIMESTAMP,
	-- Set when delivery is abandoned, e.g. no_device or blocked. Null on the normal path.
	"failed_reason" VARCHAR(60),
	PRIMARY KEY("message_id", "recipient_user_id")
);

COMMENT ON TABLE "message_receipts" IS 'The fan-out table and the largest in the schema. Timestamps rather than a status column, because the transitions are strictly ordered and a nullable time is both the flag and the audit trail.';
COMMENT ON COLUMN "message_receipts"."message_id" IS 'Message being tracked, part of the composite key.';
COMMENT ON COLUMN "message_receipts"."recipient_user_id" IS 'Recipient, part of the key. One row per recipient is the fan-out: a 200-person group produces 200 rows per message.';
COMMENT ON COLUMN "message_receipts"."delivered_at" IS 'When the recipient device acknowledged receipt. Null means the second tick has not appeared.';
COMMENT ON COLUMN "message_receipts"."read_at" IS 'When the recipient opened the chat past this message. Null means unread, or that they disabled read receipts.';
COMMENT ON COLUMN "message_receipts"."played_at" IS 'When a voice note was played, which is a third state text messages do not have.';
COMMENT ON COLUMN "message_receipts"."failed_reason" IS 'Set when delivery is abandoned, e.g. no_device or blocked. Null on the normal path.';

CREATE INDEX "idx_receipts_recipient_undelivered"
ON "message_receipts" ("recipient_user_id", "delivered_at");
CREATE INDEX "idx_receipts_message_read"
ON "message_receipts" ("message_id", "read_at");

CREATE TABLE IF NOT EXISTS "reactions" (
	-- Message reacted to, part of the composite key.
	"message_id" BIGINT,
	-- Who reacted, part of the key. One reaction per person per message - unlike most chat apps, picking a new emoji replaces the old one.
	"user_id" BIGINT,
	-- The chosen emoji. Updated in place rather than inserted again, which is why it is not part of the key.
	"emoji" VARCHAR(16) NOT NULL,
	-- When the reaction was last set.
	"reacted_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("message_id", "user_id")
);

COMMENT ON TABLE "reactions" IS 'The key is two columns, not three, and that is the product rule: a person has exactly one reaction per message and changing it is an update.';
COMMENT ON COLUMN "reactions"."message_id" IS 'Message reacted to, part of the composite key.';
COMMENT ON COLUMN "reactions"."user_id" IS 'Who reacted, part of the key. One reaction per person per message - unlike most chat apps, picking a new emoji replaces the old one.';
COMMENT ON COLUMN "reactions"."emoji" IS 'The chosen emoji. Updated in place rather than inserted again, which is why it is not part of the key.';
COMMENT ON COLUMN "reactions"."reacted_at" IS 'When the reaction was last set.';

CREATE INDEX "idx_reactions_message"
ON "reactions" ("message_id");

CREATE TABLE IF NOT EXISTS "blocks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who blocked.
	"blocker_user_id" BIGINT NOT NULL,
	-- Who was blocked. Never told, which is why this table is never read from their side.
	"blocked_user_id" BIGINT NOT NULL,
	-- Block time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "blocks" IS 'Directed and asymmetric. A blocked sender message is accepted and then never fanned out, so their client shows one tick forever and learns nothing.';
COMMENT ON COLUMN "blocks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "blocks"."blocker_user_id" IS 'Who blocked.';
COMMENT ON COLUMN "blocks"."blocked_user_id" IS 'Who was blocked. Never told, which is why this table is never read from their side.';
COMMENT ON COLUMN "blocks"."created_at" IS 'Block time.';

CREATE UNIQUE INDEX "uq_blocks_pair"
ON "blocks" ("blocker_user_id", "blocked_user_id");
CREATE INDEX "idx_blocks_blocked"
ON "blocks" ("blocked_user_id");

CREATE TABLE IF NOT EXISTS "group_invite_links" (
	-- The link code, and the primary key - the URL is the identity, so there is no surrogate id.
	"code" VARCHAR(24),
	-- Group the link joins.
	"chat_id" BIGINT NOT NULL,
	-- Admin who generated it. Null once that account is gone; the link keeps working until revoked.
	"created_by_user_id" BIGINT,
	-- Revoking sets this false rather than deleting, so an old link resolves to "this link was reset" instead of "not found".
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Joiners land in a pending queue instead of the member list.
	"requires_admin_approval" BOOLEAN NOT NULL DEFAULT false,
	-- Generation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When it was reset. Null while active.
	"revoked_at" TIMESTAMP,
	PRIMARY KEY("code")
);

COMMENT ON TABLE "group_invite_links" IS 'One active link per group in practice, with revoked rows kept. Keeping them is what lets a shared-out old link explain itself rather than 404.';
COMMENT ON COLUMN "group_invite_links"."code" IS 'The link code, and the primary key - the URL is the identity, so there is no surrogate id.';
COMMENT ON COLUMN "group_invite_links"."chat_id" IS 'Group the link joins.';
COMMENT ON COLUMN "group_invite_links"."created_by_user_id" IS 'Admin who generated it. Null once that account is gone; the link keeps working until revoked.';
COMMENT ON COLUMN "group_invite_links"."is_active" IS 'Revoking sets this false rather than deleting, so an old link resolves to "this link was reset" instead of "not found".';
COMMENT ON COLUMN "group_invite_links"."requires_admin_approval" IS 'Joiners land in a pending queue instead of the member list.';
COMMENT ON COLUMN "group_invite_links"."created_at" IS 'Generation time.';
COMMENT ON COLUMN "group_invite_links"."revoked_at" IS 'When it was reset. Null while active.';

CREATE INDEX "idx_group_invite_links_chat_active"
ON "group_invite_links" ("chat_id", "is_active");

